  static MeridianShadows lerp(MeridianShadows a, MeridianShadows b, double t) =>
      MeridianShadows(
        shadowPane: BoxShadow.lerpList(a.shadowPane, b.shadowPane, t)!,
        shadowFloat: BoxShadow.lerpList(a.shadowFloat, b.shadowFloat, t)!,
