/// A brand's corner radius scale. [pill] never changes.
@immutable
final class MeridianRadiusScale {
  const MeridianRadiusScale({
    required this.xs,
    required this.sm,
    required this.md,
    required this.lg,
    required this.xl,
  });

  /// Keycaps, status tiles, inline highlights.
  final double xs;

  /// Rows (the selection is an inset rounded bar, never full-bleed), chips, menu items, small icon buttons.
  final double sm;

  /// Buttons, fields, select, segmented track, tabs.
  final double md;

  /// Islands, banners, cards.
  final double lg;

  /// Everything that floats: menus, popovers, toasts, dialogs, the palette; the top corners of bottom sheets.
  final double xl;

  /// Count badges, switches, progress bars, avatars, pill tabs.
  static const double pill = 999.0;

  /// The default Meridian scale.
  static const standard = MeridianRadiusScale(
    xs: 3.0,
    sm: 5.0,
    md: 7.0,
    lg: 10.0,
    xl: 14.0,
  );

  /// Interpolates every step, for a theme change that animates.
  static MeridianRadiusScale lerp(
    MeridianRadiusScale a,
    MeridianRadiusScale b,
    double t,
  ) => MeridianRadiusScale(
    xs: lerpDouble(a.xs, b.xs, t)!,
    sm: lerpDouble(a.sm, b.sm, t)!,
    md: lerpDouble(a.md, b.md, t)!,
    lg: lerpDouble(a.lg, b.lg, t)!,
    xl: lerpDouble(a.xl, b.xl, t)!,
  );

  @override
  bool operator ==(Object other) =>
      other is MeridianRadiusScale &&
      other.xs == xs &&
      other.sm == sm &&
      other.md == md &&
      other.lg == lg &&
      other.xl == xl;

  @override
  int get hashCode => Object.hash(xs, sm, md, lg, xl);
}

