/// Timing curves (design/project/guides/40-motion.md).
abstract final class MeridianCurves {
  /// Moves and changes that start and end on screen.
  static const Cubic standard = Cubic(0.2, 0.0, 0.0, 1.0);

  /// Arrivals: fast start, long gentle landing.
  static const Cubic enter = Cubic(0.05, 0.7, 0.1, 1.0);

  /// Departures: accelerate away.
  static const Cubic exit = Cubic(0.3, 0.0, 0.8, 0.15);

  /// Tints and highlights fading back.
  static const Cubic exitSoft = Cubic(0.4, 0.0, 1.0, 1.0);
}

/// Durations and their curves. Honour reduce motion: see `MeridianMotion`.
abstract final class MeridianDurations {
  /// Hover fill in, and press fills.
  static const Duration hover = Duration(milliseconds: 80);
  static const Curve hoverCurve = Curves.linear;

  /// Hover fill out: slower, so sweeping the pointer across rows leaves a soft trail.
  static const Duration hoverOut = Duration(milliseconds: 160);
  static const Curve hoverOutCurve = Curves.linear;

  /// Press-in: a control scales to press-scale.
  static const Duration press = Duration(milliseconds: 60);
  static const Curve pressCurve = MeridianCurves.exit;

  /// Small flips: icon swap, count roll, check stroke, chevron rotate, colour-only changes.
  static const Duration quick = Duration(milliseconds: 100);
  static const Curve quickCurve = MeridianCurves.standard;

  /// Selection bar, toggles, tab rule when not springing.
  static const Duration select = Duration(milliseconds: 120);
  static const Curve selectCurve = MeridianCurves.standard;

  /// Anything leaving: overlays, toasts, rows, hover actions.
  static const Duration exit = Duration(milliseconds: 100);
  static const Curve exitCurve = MeridianCurves.exit;

  /// Menus, popovers, suggestions and tooltips entering: fade in while rising 4px.
  static const Duration overlay = Duration(milliseconds: 140);
  static const Curve overlayCurve = MeridianCurves.enter;

  /// Dialog and sheet surface entering; scrim fade.
  static const Duration dialog = Duration(milliseconds: 200);
  static const Curve dialogCurve = MeridianCurves.enter;

  /// Size changes: disclosure, banner, row insert or remove, button width, reveal.
  static const Duration layout = Duration(milliseconds: 200);
  static const Curve layoutCurve = MeridianCurves.standard;

  /// Bottom sheets and side panels sliding in.
  static const Duration sheet = Duration(milliseconds: 240);
  static const Curve sheetCurve = MeridianCurves.enter;

  /// Values in live lists and meters moving to a new value.
  static const Duration emphasized = Duration(milliseconds: 240);
  static const Curve emphasizedCurve = MeridianCurves.standard;

  /// An app's signature moment, e.g. an item travelling to its new home.
  static const Duration highlight = Duration(milliseconds: 320);
  static const Curve highlightCurve = MeridianCurves.standard;

  /// A rare success moment; at most one per action the person took.
  static const Duration celebrate = Duration(milliseconds: 520);
  static const Curve celebrateCurve = MeridianCurves.standard;

  /// A changed item's accent-soft tint fading back to normal.
  static const Duration attention = Duration(milliseconds: 900);
  static const Curve attentionCurve = MeridianCurves.exitSoft;

  /// The crossfade that replaces movement under reduce motion (MeridianMotion.fade).
  static const Duration reducedFade = Duration(milliseconds: 100);
  static const Curve reducedFadeCurve = Curves.linear;

  /// Delay between successive items in an entrance; at most stagger-max items are staggered.
  static const Duration stagger = Duration(milliseconds: 18);
  static const Curve staggerCurve = Curves.linear;

  /// Wait before a spinner or busy state appears, so fast work never flashes.
  static const Duration spinnerDelay = Duration(milliseconds: 150);
  static const Curve spinnerDelayCurve = Curves.linear;

  /// One field shake (MM-09).
  static const Duration shakeField = Duration(milliseconds: 240);
  static const Curve shakeFieldCurve = Curves.linear;

  /// One dialog shake (MM-47).
  static const Duration shakeSurface = Duration(milliseconds: 280);
  static const Curve shakeSurfaceCurve = Curves.linear;

  /// A toolbar icon's nudge out (MM-07); the return is spring-snappy.
  static const Duration nudge = Duration(milliseconds: 90);
  static const Curve nudgeCurve = MeridianCurves.standard;

  /// How long a success check stays (MM-04).
  static const Duration hold = Duration(milliseconds: 900);
  static const Curve holdCurve = Curves.linear;

  /// A progress bar at 100% waits this long before it fades (MM-63).
  static const Duration progressHold = Duration(milliseconds: 300);
  static const Curve progressHoldCurve = Curves.linear;

  /// Delay before a tooltip shows.
  static const Duration tooltipWait = Duration(milliseconds: 500);
  static const Curve tooltipWaitCurve = Curves.linear;

  /// Reserved: after a tooltip hides, the next one within this window shows at once.
  static const Duration tooltipWarm = Duration(milliseconds: 800);
  static const Curve tooltipWarmCurve = Curves.linear;

  /// One loop of a live halo.
  static const Duration pulse = Duration(milliseconds: 1600);
  static const Curve pulseCurve = MeridianCurves.standard;

  /// One half-cycle of a skeleton's breathing.
  static const Duration skeletonPulse = Duration(milliseconds: 1200);
  static const Curve skeletonPulseCurve = MeridianCurves.standard;

  /// One period of a drop zone's marching dashes (MM-77).
  static const Duration march = Duration(milliseconds: 600);
  static const Curve marchCurve = Curves.linear;

  /// One spinner turn (2000 with reduce motion).
  static const Duration spinner = Duration(milliseconds: 700);
  static const Curve spinnerCurve = Curves.linear;

  /// One spinner turn with reduce motion.
  static const Duration spinnerReduced = Duration(milliseconds: 2000);
  static const Curve spinnerReducedCurve = Curves.linear;

  /// One sweep of the indeterminate progress bar.
  static const Duration progress = Duration(milliseconds: 1100);
  static const Curve progressCurve = Curves.easeInOut;

  /// Wait before skeletons appear, so fast loads never flash them.
  static const Duration skeletonDelay = Duration(milliseconds: 300);
  static const Curve skeletonDelayCurve = Curves.linear;

  /// How long a toast stays.
  static const Duration toast = Duration(milliseconds: 4000);
  static const Curve toastCurve = Curves.linear;

  /// How long a toast with an action (Undo) stays.
  static const Duration toastAction = Duration(milliseconds: 8000);
  static const Curve toastActionCurve = Curves.linear;
}

