/// Foreground colours of code token categories for one theme, shared by
/// every brand. Plain code is `ink`.
@immutable
final class MeridianSyntaxColors {
  const MeridianSyntaxColors({
    required this.comment,
    required this.keyword,
    required this.string,
    required this.number,
    required this.type,
    required this.function,
    required this.variable,
    required this.constant,
    required this.operator,
    required this.punctuation,
    required this.attribute,
    required this.tag,
  });

  /// The light theme's colours.
  static const light = MeridianSyntaxColors(
    comment: Color(0xFF5C6870),
    keyword: Color(0xFF8A2F8C),
    string: Color(0xFF0B6157),
    number: Color(0xFF0B5A96),
    type: Color(0xFF8C3A62),
    function: Color(0xFF5241A8),
    variable: Color(0xFF2C4A5C),
    constant: Color(0xFF0B5A96),
    operator: Color(0xFF4B5962),
    punctuation: Color(0xFF4B5962),
    attribute: Color(0xFF7A4A00),
    tag: Color(0xFF8A2F8C),
  );

  /// The dark theme's colours.
  static const dark = MeridianSyntaxColors(
    comment: Color(0xFF8C9EA7),
    keyword: Color(0xFFDDA0E6),
    string: Color(0xFF7FD3C4),
    number: Color(0xFF8FC6F2),
    type: Color(0xFFEBA6C5),
    function: Color(0xFFB9AEF7),
    variable: Color(0xFFCBD9E0),
    constant: Color(0xFF8FC6F2),
    operator: Color(0xFFA9B8BF),
    punctuation: Color(0xFFA9B8BF),
    attribute: Color(0xFFE8BE7C),
    tag: Color(0xFFDDA0E6),
  );

  /// The colours for [brightness].
  static MeridianSyntaxColors resolve(Brightness brightness) =>
      brightness == Brightness.dark ? dark : light;

  /// Comments and documentation comments. Code text on `pane`, `pane-alt`, `raised`, `pane-hover`, `success-bg` and `danger-bg` (at least 4.5:1).
  final Color comment;

  /// Keywords: declaration, control and storage words. Code text on `pane`, `pane-alt`, `raised`, `pane-hover`, `success-bg` and `danger-bg` (at least 4.5:1).
  final Color keyword;

  /// String and character literals, with their escapes and interpolations. Code text on `pane`, `pane-alt`, `raised`, `pane-hover`, `success-bg` and `danger-bg` (at least 4.5:1).
  final Color string;

  /// Numeric literals. Code text on `pane`, `pane-alt`, `raised`, `pane-hover`, `success-bg` and `danger-bg` (at least 4.5:1).
  final Color number;

  /// Type, class and namespace names. Code text on `pane`, `pane-alt`, `raised`, `pane-hover`, `success-bg` and `danger-bg` (at least 4.5:1).
  final Color type;

  /// Function and method names, where declared and where called. Code text on `pane`, `pane-alt`, `raised`, `pane-hover`, `success-bg` and `danger-bg` (at least 4.5:1).
  final Color function;

  /// Variables and parameters a grammar names as such. Code text on `pane`, `pane-alt`, `raised`, `pane-hover`, `success-bg` and `danger-bg` (at least 4.5:1).
  final Color variable;

  /// Language constants (true, null), named constants and enum values. Code text on `pane`, `pane-alt`, `raised`, `pane-hover`, `success-bg` and `danger-bg` (at least 4.5:1).
  final Color constant;

  /// Operators. Code text on `pane`, `pane-alt`, `raised`, `pane-hover`, `success-bg` and `danger-bg` (at least 4.5:1).
  final Color operator;

  /// Delimiters, separators and terminators. Code text on `pane`, `pane-alt`, `raised`, `pane-hover`, `success-bg` and `danger-bg` (at least 4.5:1).
  final Color punctuation;

  /// Annotations, attributes and markup attribute names. Code text on `pane`, `pane-alt`, `raised`, `pane-hover`, `success-bg` and `danger-bg` (at least 4.5:1).
  final Color attribute;

  /// Markup tag names. Code text on `pane`, `pane-alt`, `raised`, `pane-hover`, `success-bg` and `danger-bg` (at least 4.5:1).
  final Color tag;

  static MeridianSyntaxColors lerp(
    MeridianSyntaxColors a,
    MeridianSyntaxColors b,
    double t,
  ) => MeridianSyntaxColors(
    comment: Color.lerp(a.comment, b.comment, t)!,
    keyword: Color.lerp(a.keyword, b.keyword, t)!,
    string: Color.lerp(a.string, b.string, t)!,
    number: Color.lerp(a.number, b.number, t)!,
    type: Color.lerp(a.type, b.type, t)!,
    function: Color.lerp(a.function, b.function, t)!,
    variable: Color.lerp(a.variable, b.variable, t)!,
    constant: Color.lerp(a.constant, b.constant, t)!,
    operator: Color.lerp(a.operator, b.operator, t)!,
    punctuation: Color.lerp(a.punctuation, b.punctuation, t)!,
    attribute: Color.lerp(a.attribute, b.attribute, t)!,
    tag: Color.lerp(a.tag, b.tag, t)!,
  );

  @override
  bool operator ==(Object other) =>
      other is MeridianSyntaxColors &&
      other.comment == comment &&
      other.keyword == keyword &&
      other.string == string &&
      other.number == number &&
      other.type == type &&
      other.function == function &&
      other.variable == variable &&
      other.constant == constant &&
      other.operator == operator &&
      other.punctuation == punctuation &&
      other.attribute == attribute &&
      other.tag == tag;

  @override
  int get hashCode => Object.hashAll([
    comment,
    keyword,
    string,
    number,
    type,
    function,
    variable,
    constant,
    operator,
    punctuation,
    attribute,
    tag,
  ]);
}
